--------------------------------------------------------------------------------
-- Index fragmentation report + optional rebuild (SQL Server T-SQL)
-- Run in the target database context (e.g., USE YourDatabase;)
--
-- This was generated by Duck.ai (GPT-5 mini) on 03/31/26
--------------------------------------------------------------------------------

-- Parameters: adjust if desired
DECLARE @MinPageCount INT = 100;         -- only consider indexes with at least this many pages
DECLARE @ReorgThreshold FLOAT = 5.0;    -- >= this and <= @RebuildThreshold => REORGANIZE
DECLARE @RebuildThreshold FLOAT = 30.0; -- > this => REBUILD
DECLARE @OnlineRebuild BIT = 1;         -- 1 = attempt ONLINE = ON (Enterprise/appropriate SKUs), 0 = OFF

--------------------------------------------------------------------------------
-- Fragmentation report (sorted highest fragmentation first)
--------------------------------------------------------------------------------
;WITH frag AS (
    SELECT
        DB_ID()                               AS database_id,
        OBJECT_SCHEMA_NAME(ps.object_id)      AS schema_name,
        OBJECT_NAME(ps.object_id)             AS table_name,
        ps.object_id,
        ps.index_id,
        i.name                                AS index_name,
        ips.index_type_desc,
        ips.avg_fragmentation_in_percent,
        ips.fragment_count,
        ips.page_count,
        ips.avg_fragment_size_in_pages,
        ps.rows /*
        ps.row_count,
        ps.reserved_page_count,
        ps.used_page_count */
    FROM
        sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') AS ips
        INNER JOIN sys.partitions AS ps
            ON ips.object_id = ps.object_id
            AND ips.index_id = ps.index_id
        LEFT JOIN sys.indexes AS i
            ON ips.object_id = i.object_id
            AND ips.index_id = i.index_id
    WHERE
        ips.database_id = DB_ID()
        AND ps.index_id > 0               -- exclude heaps (index_id = 0)
)
SELECT
    schema_name,
    table_name,
    index_id,
    ISNULL(index_name, '<HEAP>')                  AS index_name,
    index_type_desc,
    avg_fragmentation_in_percent,
    fragment_count,
    page_count,
    avg_fragment_size_in_pages,
    rows /*
    row_count,
    reserved_page_count,
    used_page_count */
FROM
    frag
WHERE
    page_count >= @MinPageCount
ORDER BY
    avg_fragmentation_in_percent DESC,
    fragment_count DESC,
    page_count DESC;

--------------------------------------------------------------------------------
-- Optional: Rebuild or Reorganize indexes based on thresholds
-- NOTE: Uncomment the EXEC block below to apply changes.
-- Always test on non-production first and consider maintenance windows.
--------------------------------------------------------------------------------

